import {test,expect} from 'bun:test';
import {validatePhysicalModel,physicalDependencies} from '../src/core/physical-model.js';
export const fixture=()=>({schema:1,units:'m-kg-s-rad',bodies:['a','b','c'].map((id,i)=>({id,parts:[id],fixed:i===0,position:[i,0,0],inertial:{mass:1,center:[0,0,0],tensor:[.1,.1,.1,0,0,0]},collision:{shapes:[{kind:'ball',radius:.1,center:[0,0,0]}],friction:.3,restitution:0,membership:1<<i,filter:1<<i},provenance:{status:'estimated',evidence:'test'}})),joints:[{id:'ab',type:'prismatic',parent:'a',child:'b',anchorParent:[0,0,0],anchorChild:[0,0,0],axis:[1,0,0],damping:.1,limits:[0,2]}]});
test('dependency graph joins fixed/prismatic joints and potential contacts, leaves isolated bodies independent',()=>{const m=fixture();expect(physicalDependencies(m).components).toEqual([['a','b'],['c']]);m.bodies[1].collision.filter=7;m.bodies[2].collision.filter=7;expect(physicalDependencies(m).components).toEqual([['a','b','c']]);});
test('rejects invalid tensor, unowned geometry, units and unsupported fields',()=>{const m=fixture();expect(()=>validatePhysicalModel(m,['a','b','c','missing'])).toThrow('lacks');m.bodies[0].inertial.tensor=[10,1,1,0,0,0];expect(()=>validatePhysicalModel(m)).toThrow('inequalities');m.bodies[0].inertial.tensor=[1,1,1,2,0,0];expect(()=>validatePhysicalModel(m)).toThrow('positive');const n=fixture();n.units='mm';expect(()=>validatePhysicalModel(n)).toThrow('SI');const p=fixture();p.joints[0].foo=true;expect(()=>validatePhysicalModel(p)).toThrow('fields');});

test('pinned mesh colliders require relative immutable assets and explicit cooking',()=>{const m=fixture(),shape={kind:'mesh_file',file:'physics/hood.ctm',sha256:'a'.repeat(64),cooking:'convex_decomposition',center:[0,0,0],rotation:[0,0,0]};m.bodies[1].collision.shapes=[shape];expect(validatePhysicalModel(m).bodies[1].collision.shapes[0]).toEqual(shape);for(const file of ['../hood.ctm','/hood.ctm','x/../hood.ctm','C:/hood.ctm','x\\hood.ctm']){shape.file=file;expect(()=>validatePhysicalModel(m)).toThrow('mesh collider');}shape.file='physics/hood.ctm';shape.cooking='trimesh';expect(()=>validatePhysicalModel(m)).toThrow('convex cooking');m.bodies[1].fixed=true;expect(validatePhysicalModel(m).bodies[1].collision.shapes[0].cooking).toBe('trimesh');shape.sha256='not-a-pin';expect(()=>validatePhysicalModel(m)).toThrow('mesh collider');});

export const compliantFixture=()=>{const m=fixture();m.joints=[];const b=m.bodies[1],r=b.collision.shapes[0].radius,I=.4*b.inertial.mass*r*r;b.inertial.tensor=[I,I,I,0,0,0];b.compliance={frequencyHz:30,subdivisions:1,entryMargin:.03,exitMargin:.1,recoveryTolerance:.0005};m.complianceZones=[{body:'a',center:[0,0,0],half:[.2,.2,.2],lookahead:.03}];return m;};
test('sphere compliance requires explicit calibration and activation dependency across masks',()=>{const m=compliantFixture();expect(validatePhysicalModel(m).bodies[1].compliance.frequencyHz).toBe(30);expect(physicalDependencies(m).components).toEqual([['a','b'],['c']]);delete m.complianceZones;expect(()=>validatePhysicalModel(m)).toThrow('activation zones');});
test('sphere compliance rejects incompatible inertia, joint ownership and unsafe parameters',()=>{for(const mutate of [m=>m.bodies[1].inertial.tensor=[.1,.1,.1,0,0,0],m=>m.bodies[1].compliance.frequencyHz=Infinity,m=>m.bodies[1].compliance.entryMargin=1e-100,m=>m.bodies[1].compliance.exitMargin=1e100,m=>m.complianceZones[0].center=[1e100,0,0],m=>m.bodies[1].compliance.subdivisions=3,m=>m.bodies[1].compliance.recoveryTolerance=.01,m=>m.complianceZones[0].lookahead=.001,m=>m.complianceZones[0].body='b',m=>m.bodies[1].fixed=true,m=>m.joints=fixture().joints]){const m=compliantFixture();mutate(m);expect(()=>validatePhysicalModel(m)).toThrow();}});
